SELECT
,mi.project_code AS projectCode ,mi.project_name AS projectName FROM mold_ref_sku mrs left join mold_info mi on mi.id = mrs.mold_id and mi.is_deleted = FALSE WHERE ${params.sqlMap.default} AND mrs.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}

SELECT approve_status AS tabFlag, count(*) AS count FROM mold_ref_sku WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
